import { useId, useState } from 'react';
import type { CSSProperties, FormEvent } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import toast from 'react-hot-toast';
import { useAuth } from '../context/AuthContext';
import { homeDoUsuario } from '../lib/perfil';
import './ReversoLoginAzime.css';

// Imagens originais em alta definição, incorporadas para dispensar arquivos externos.
const LOGO = {
  w: 1678,
  h: 551,
  light: 'data:image/png;base64,',
  dark: 'data:image/png;base64,',
} as const;

const SLICES = 6;
const WIDTH = 620;
const HEIGHT = WIDTH * LOGO.h / LOGO.w;
const X = (900 - WIDTH) / 2;
const Y = (680 - HEIGHT) / 2;

type ArtProps = { dark: boolean };

function caminhoInternoSolicitado(state: unknown): string | null {
  if (!state || typeof state !== 'object') return null;
  const from = (state as { from?: { pathname?: unknown; search?: unknown; hash?: unknown } }).from;
  if (!from || typeof from.pathname !== 'string' || !from.pathname.startsWith('/admin/') || /[?#]/.test(from.pathname)) return null;
  const search = typeof from.search === 'string' && from.search.startsWith('?') ? from.search : '';
  const hash = typeof from.hash === 'string' && from.hash.startsWith('#') ? from.hash : '';
  return `${from.pathname}${search}${hash}`;
}

function AzimeArt({ dark }: ArtProps) {
  const id = `azl-${useId().replace(/[^a-zA-Z0-9_-]/g, '_')}`;
  const scanId = `${id}-scan`;
  const glowId = `${id}-glow`;
  const slices = Array.from({ length: SLICES }, (_, i) => i);
  const href = dark ? LOGO.dark : LOGO.light;

  return (
    <svg viewBox="0 0 900 680" role="img" aria-label="Animação de azime">
      <defs>
        {slices.map((i) => (
          <clipPath id={`${id}-clip-${i}`} key={i}>
            <rect x={X - 4} y={Y + HEIGHT * i / SLICES} width={WIDTH + 8}
              height={HEIGHT / SLICES + 1.5} rx={2} />
          </clipPath>
        ))}
        <linearGradient id={scanId} x1="0" y1="0" x2="1" y2="0">
          <stop stopColor="var(--ink)" stopOpacity={0} />
          <stop offset=".5" stopColor="var(--ink)" stopOpacity={.82} />
          <stop offset="1" stopColor="var(--ink)" stopOpacity={0} />
        </linearGradient>
        <filter id={glowId} x="-15%" y="-35%" width="130%" height="170%">
          <feDropShadow dx={0} dy={16} stdDeviation={18} floodColor="#000000" floodOpacity={.18} />
        </filter>
      </defs>
      <g className="azl-azframe" fill="none" stroke="var(--detail)" strokeWidth={1} opacity={.28}>
        <path d="M148 254v-18h18M752 254v-18h-18M148 426v18h18M752 426v18h-18" />
      </g>
      <g filter={`url(#${glowId})`}>
        {slices.map((i) => {
          const style = {
            '--dx': `${i % 2 ? 62 : -62}px`,
            '--dy': `${(i - (SLICES - 1) / 2) * 8}px`,
            '--d': `${i * .055}s`,
          } as CSSProperties;
          return (
            <g key={i} className="azl-azslice" style={style}>
              <g clipPath={`url(#${id}-clip-${i})`}>
                <image href={href} x={X} y={Y} width={WIDTH} height={HEIGHT}
                  preserveAspectRatio="xMidYMid meet" className="azl-logo-image" />
              </g>
            </g>
          );
        })}
      </g>
      <rect className="azl-azscan" x={X + WIDTH * .38} y={Y - 18}
        width={Math.max(72, WIDTH * .11)} height={HEIGHT + 36}
        fill={`url(#${scanId})`} opacity={.24} rx={28} />
    </svg>
  );
}

export default function ReversoLoginAzime() {
  const { login } = useAuth();
  const navigate = useNavigate();
  const location = useLocation();
  const retornoSolicitado = caminhoInternoSolicitado(location.state);
  const [dark, setDark] = useState(false);
  const [paused, setPaused] = useState(false);
  const [showPassword, setShowPassword] = useState(false);
  const [enviando, setEnviando] = useState(false);

  function toggleTheme() {
    setDark((value) => !value);
  }

  async function handleSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    const dados = new FormData(event.currentTarget);
    const usuario = String(dados.get('username') ?? '');
    const senha = String(dados.get('password') ?? '');
    if (!usuario.trim() || !senha) {
      toast.error('Informe seu usuário e sua senha.');
      return;
    }

    setEnviando(true);
    try {
      const sessao = await login(usuario, senha);
      toast.success(`Bem-vindo, ${sessao.nome}.`);
      navigate(retornoSolicitado ?? homeDoUsuario(sessao), { replace: true });
    } catch (error) {
      toast.error(error instanceof Error ? error.message : 'Falha ao entrar.');
    } finally {
      setEnviando(false);
    }
  }

  return (
    <div className={`azime-login${dark ? ' dark' : ''}`}>
      <div className="azl-shell">
        <main>
          <section className={`azl-hero${paused ? ' azl-paused' : ''}`} aria-label="Identidade da empresa">
            <div><AzimeArt dark={dark} /></div>
            <button type="button" className="azl-pause" onClick={() => setPaused((value) => !value)}
              aria-label={paused ? 'Retomar animação' : 'Pausar animação'}>
              {paused ? '▶' : 'Ⅱ'}
            </button>
          </section>
          <section className="azl-panel">
            <button type="button" className="azl-theme" onClick={toggleTheme}
              aria-label={dark ? 'Ativar modo claro' : 'Ativar modo escuro'}
              title={dark ? 'Modo claro' : 'Modo escuro'}>
              <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={1.5} aria-hidden="true">
                {dark ? <>
                  <circle cx={12} cy={12} r={4} />
                  <path d="M12 1v3m0 16v3M1 12h3m16 0h3M4 4l2 2m12 12 2 2M4 20l2-2M18 6l2-2" />
                </> : <path d="M20 15A9 9 0 0 1 9 4a9 9 0 1 0 11 11Z" />}
              </svg>
            </button>
            <form className="azl-form" onSubmit={handleSubmit}>
              <h1>Entrar</h1>
              <label className="azl-field">Usuário
                <span className="azl-input">
                  <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={1.6} aria-hidden="true">
                    <circle cx={12} cy={8} r={4} />
                    <path d="M4 21v-2a8 8 0 0 1 16 0v2" />
                  </svg>
                  <input name="username" autoComplete="username" required />
                </span>
              </label>
              <label className="azl-field">Senha
                <span className="azl-input">
                  <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={1.6} aria-hidden="true">
                    <rect x={5} y={10} width={14} height={11} rx={3} />
                    <path d="M8 10V7a4 4 0 0 1 8 0v3" />
                  </svg>
                  <input name="password" type={showPassword ? 'text' : 'password'} autoComplete="current-password" required />
                  <button type="button" aria-label={showPassword ? 'Ocultar senha' : 'Mostrar senha'}
                    onClick={() => setShowPassword((value) => !value)}>
                    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={1.6} aria-hidden="true">
                      <path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7-10-7-10-7Z" />
                      <circle cx={12} cy={12} r={3} />
                    </svg>
                  </button>
                </span>
              </label>
              <button type="submit" className="azl-cta" disabled={enviando}>
                Entrar
                <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={1.7} aria-hidden="true">
                  <path d="M4 12h15m-6-6 6 6-6 6" />
                </svg>
              </button>
              <div className="azl-foot">Reverso</div>
            </form>
          </section>
        </main>
      </div>
    </div>
  );
}
